import{_ as o,a0 as d,w as r,s as l,ao as a,I as i,x as t,a1 as s,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse(`{"title":"用命令行工具Speedtest-CLI来测试你的上下行网速 | LCTT x X-CMD","titleTemplate":false,"description":"用命令行工具Speedtest-CLI来测试你的上下行网速 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用命令行工具Speedtest-CLI来测试你的上下行网速 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用命令行工具Speedtest-CLI来测试你的上下行网速 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150316 How to Test Your Internet Speed Bidirectionally from Command Line Using 'Speedtest-CLI' Tool","title":"用命令行工具Speedtest-CLI来测试你的上下行网速","tag":"201506","desc":""},"relativePath":"201506/20150316 How to Test Your Internet Speed Bidirectionally from Command Line Using 'Speedtest-CLI' Tool.md","filePath":"[post].md"}`),c={name:"201506/20150316 How to Test Your Internet Speed Bidirectionally from Command Line Using 'Speedtest-CLI' Tool.md"};function m(h,e,w,u,g,S){const p=d("Link");return r(),l("div",null,[e[16]||(e[16]=a(`<h1 id="用命令行工具speedtest-cli来测试你的上下行网速" tabindex="-1">用命令行工具Speedtest-CLI来测试你的上下行网速 <a class="header-anchor" href="#用命令行工具speedtest-cli来测试你的上下行网速" aria-label="Permalink to “用命令行工具Speedtest-CLI来测试你的上下行网速”">​</a></h1><p>我们经常需要到检查家里与办公室之间的网络是否连通，那么我们要怎么做呢？打开网站Speedtest.net然后开始测试。网站是通过加载浏览器中的JavaScript脚本然后选择最佳的服务器测速然后用Flash产生图形化的结果。</p><p>那么远程服务器呢？要知道大多数远程服务器是没有浏览器可以打开web页面的。用浏览器打开网页测速的瓶颈就在此，你不能按计划的对服务器进行定期的常规测试。这时需要到一个名为Speedtest-cli的软件来打破这个瓶颈，它能让你通过命令行来测试互联网连接的速度。</p><h4 id="speedtest-cli是什么" tabindex="-1">Speedtest-cli是什么 <a class="header-anchor" href="#speedtest-cli是什么" aria-label="Permalink to “Speedtest-cli是什么”">​</a></h4><p>此程序是基于Python开发的脚本程序，利用了speedtest.net的服务来测量出上下行的宽带。Speedtest-cli能根据机房离测速服务器的物理距离来列出测速服务器，或者针对某一服务器进行测速，同时还能为你生成一个URL以便你分享你的测速结果。</p><p>要在Linux上安装最新版本的speedtest-cli，你必须安装2.4-3.4或者更高版本的Python。</p><h3 id="在linux上安装speedtest-cli" tabindex="-1">在Linux上安装speedtest-cli <a class="header-anchor" href="#在linux上安装speedtest-cli" aria-label="Permalink to “在Linux上安装speedtest-cli”">​</a></h3><p>有两种方法可以安装speedtest-cli。第一种方法需要用到<code>python-pip</code>包管理器，第二种方法需要安装Python脚本，生成安装文件然后运行，这里我们分别介绍两种方法：</p><h4 id="使用pythin-pip安装speedtest-cli" tabindex="-1">使用pythin-pip安装speedtest-cli#### <a class="header-anchor" href="#使用pythin-pip安装speedtest-cli" aria-label="Permalink to “使用pythin-pip安装speedtest-cli####”">​</a></h4><p>首先你需要安装<code>python-pip</code>包管理器，之后你就可以用pip命令来安装speedtest-cli</p><pre><code>$ sudo apt-get install python-pip
$ sudo pip install speedtest-cli
</code></pre><p>如果要把speedtest-cli升级至最新版本，你需要输入以下命令</p><pre><code>$ sudo pip install speedtest-cli --upgrade
</code></pre><h4 id="通过pyhton脚本来安装speedtest-cli" tabindex="-1">通过Pyhton脚本来安装speedtest-cli <a class="header-anchor" href="#通过pyhton脚本来安装speedtest-cli" aria-label="Permalink to “通过Pyhton脚本来安装speedtest-cli”">​</a></h4><p>首先要用wget命令从github上下来Python脚本，然后解压提取下载的文件（master.zip）</p><pre><code>$ wget https://github.com/sivel/speedtest-cli/archive/master.zip
$ unzip master.zip 
</code></pre><p>提取出文件后，进入提取出的目录<code>speedtest-cli-master</code>然后使脚本可以执行。</p><pre><code>$ cd speedtest-cli-master/
$ chmod 755 speedtest_cli.py 
</code></pre><p>下一步，把可执行的脚本移动到<code>/usr/bin</code>文件夹，这样你就不用每次都输入完整的脚本路径了。</p><pre><code>$ sudo mv speedtest_cli.py /usr/bin/
</code></pre><h3 id="用speedtest-cli测试互联网连通速度" tabindex="-1">用speedtest-cli测试互联网连通速度### <a class="header-anchor" href="#用speedtest-cli测试互联网连通速度" aria-label="Permalink to “用speedtest-cli测试互联网连通速度###”">​</a></h3><p><strong>1. 要测试你的下载与上传速度，只需要运行<code>speedtest-cli</code>命令，不需要带参数。</strong></p><pre><code>$ speedtest_cli.py
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Test-Download-Upload-Speed-in-Linux1.png" alt="Test Download Upload Speed in Linux"></p><p><em>在Linux下测试上传下载速度</em></p><p><strong>2. 测试上传下载的速度（以字节计算）</strong></p><pre><code>$ speedtest_cli.py --bytes
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Test-Speed-in-Bytes.png" alt="Test Internet Speed in Bytes"></p><p><em>测试bytes的速度</em></p><p><strong>3. 工具提供一个链接来下载由你的宽带测试结果生成的图片，你可以分享给你的家人朋友。</strong></p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Share-Internet-Speed-Results.png" alt="Share Internet Speed Results"></p><p><em>分享测速结果</em></p><p>下面的图片就是你通过以上的命令行测速而生成的图片</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Speed-Test-Results.png" alt="Speed Test Results"></p><p><em>测速结果</em></p><p><strong>4.如果你仅仅需要Ping，上传，下载的结果，就运行以下命令：</strong></p><pre><code>$ speedtest_cli.py --simple
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Test-Ping-Download-Upload-Speed1.png" alt="Test Ping Download Upload Speed"></p><p><em>测试Ping，上传，下载的速度</em></p><p><strong>5. 列出<code>speedtest.net</code>所有的服务器距离你的物理距离，单位是千米（km）</strong></p><pre><code>$ speedtest_cli.py --list
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Check-Speedtest-Servers.png" alt="Check Speedtest.net Servers"></p><p><em>列出Speedtest.net的服务器</em></p><p><strong>6. 当获得一个非常长的服务器列表之后，怎么列出我想要的某个服务器？如果我要在speedtest.net服务器列表中找出位于Mumbai（印度）的服务器呢？</strong></p><pre><code>$ speedtest_cli.py --list | grep -i Mumbai
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Check-Nearest-Server.png" alt="Check Nearest Server"></p><p><em>列出最近的服务器</em></p><p><strong>7. 对指定的服务器进行测速。我们使用上面例子5和例子6中获取的服务器ID:</strong></p><pre><code>$ speedtest_cli.py --server [server ID]
$ speedtest_cli.py --server [5060]              ## 这里使用服务器ID为5060作为例子
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Test-Connection-Against-Server.png" alt="Test Connection Against Server"></p><p><em>对指定的服务器进行测速</em></p><p><strong>8. 输出<code>speedtest-cli</code>的版本信息和帮助文档</strong></p><pre><code>$ speedtest_cli.py --version
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Check-SpeedCLi-Version.png" alt="Check SpeedCli Version"></p><p><em>输出版本号</em></p><pre><code>$ speedtest_cli.py --help
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/SpeedCli-Help.png" alt="SpeedCli Help"></p><p><em>输出帮助文档</em></p><p><strong>提醒：</strong>报告中的延迟并不是确切的结果，不应该过于依赖它；这个数值可以当作相对延迟，这对你选择某一测试服务器来说是可靠的。同时，CPU和内存的容量会影响结果的准确度。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>系统管理员和开发者应该必备这个简单的脚本工具，这个轻量级的工具功能齐全，真是太赞了。我不喜欢Speedtest.net的原因是它使用来flash，相反speedtest-cli刚好戳中了我的痛点。</p>`,61)),i("p",null,[e[1]||(e[1]=t("speedtest_cli是一个第三方工具，也不能自动地记录下宽带速度。Speedtest.net拥有上百万的用户，你可以自己",-1)),s(p,{href:"http://www.tecmint.com/speedtest-mini-server-to-test-bandwidth-speed/"},{default:n(()=>[...e[0]||(e[0]=[t("配制一个小型的测速服务器",-1)])]),_:1}),e[2]||(e[2]=t("。",-1))]),e[17]||(e[17]=i("p",null,"上面就是所有内容，更多内容敬请关注我们。如果你有任何反馈记得在文章下方评论，如果你喜欢别忘了给我们点个赞，分享我们的文章。",-1)),e[18]||(e[18]=i("hr",null,null,-1)),i("p",null,[e[4]||(e[4]=t("via: ",-1)),s(p,{href:"http://www.tecmint.com/check-internet-speed-from-command-line-in-linux/"},{default:n(()=>[...e[3]||(e[3]=[t("http://www.tecmint.com/check-internet-speed-from-command-line-in-linux/",-1)])]),_:1})]),i("p",null,[e[8]||(e[8]=t("作者：",-1)),s(p,{href:"http://www.tecmint.com/author/avishek/"},{default:n(()=>[...e[5]||(e[5]=[t("Avishek Kumar",-1)])]),_:1}),e[9]||(e[9]=t(" 译者：",-1)),s(p,{href:"https://github.com/NearTan"},{default:n(()=>[...e[6]||(e[6]=[t("NearTan",-1)])]),_:1}),e[10]||(e[10]=t(" 校对：",-1)),s(p,{href:"https://github.com/wxy"},{default:n(()=>[...e[7]||(e[7]=[t("wxy",-1)])]),_:1})]),i("p",null,[e[13]||(e[13]=t("本文由 ",-1)),s(p,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[11]||(e[11]=[t("LCTT",-1)])]),_:1}),e[14]||(e[14]=t(" 原创翻译，",-1)),s(p,{href:"http://linux.cn/"},{default:n(()=>[...e[12]||(e[12]=[t("Linux中国",-1)])]),_:1}),e[15]||(e[15]=t(" 荣誉推出",-1))])])}const y=o(c,[["render",m]]);export{f as __pageData,y as default};
